1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
45	const LOYALTY_DISCOUNT = -0.2;
46	const FOLLOW_UP_CONTRACT_DISCOUNT = -0.15;
47	/** Levied on every quote, not only the customer's first — see the policy-wide modifier rules. */
48	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
49	
50	/** The MHPCO price list; only the types pinned down by tests so far. */
51	const BASE_PREMIUMS: Record<string, number | undefined> = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	  potion: 40,
56	  rune: 25,
57	  moonstone: 25,
58	};
59	
60	/** What each item is insured for; distinct from what it costs to insure. */
61	const INSURANCE_VALUES: Record<string, number | undefined> = {
62	  sword: 1000,
63	  amulet: 600,
64	  staff: 800,
65	  potion: 400,
66	  rune: 250,
67	  moonstone: 250,
68	};
69	
70	const DEDUCTIBLE_PER_DAMAGE = 100;
71	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
72	
73	/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
74	const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));
75	
76	/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
77	const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));
78	
79	const basePremiumFor = (item: Item): number => {
80	  const basePremium = BASE_PREMIUMS[item.type];
81	  if (basePremium === undefined) throw new Error(`Unknown item type: ${item.type}`);
82	  return basePremium;
83	};
84	
85	const sumOf = <T>(values: T[], amountOf: (value: T) => number): number =>
86	  values.reduce((total, value) => total + amountOf(value), 0);
87	
88	/** A building block of 3 alike components is offered at a special base premium. */
89	const BLOCK_SIZE = 3;
90	const BLOCK_BASE_PREMIUM = 60;
91	
92	/** Components are the small parts; main items never qualify for block pricing. */
93	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
94	
95	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
96	
97	const alikeComponentGroups = (items: Item[]): Item[][] => [
98	  ...items
99	    .reduce(
100	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
101	      new Map<string, Item[]>(),
102	    )
103	    .values(),
104	];
105	
106	const isBlock = (group: Item[]): boolean =>
107	  group.length === BLOCK_SIZE && group.every(isComponent);
108	
109	const basePremiumForGroup = (group: Item[]): number =>
110	  isBlock(group) ? BLOCK_BASE_PREMIUM : sumOf(group, basePremiumFor);
111	
112	const HIGH_ENCHANTMENT_THRESHOLD = 5;
113	
114	const isCursed = (item: Item): boolean => item.cursed === true;
115	
116	const isHighlyEnchanted = (item: Item): boolean =>
117	  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD;
118	
119	/**
120	 * A modifier raises or lowers the amount it applies to by `rate`, but only for
121	 * subjects it applies to. Modifiers that apply stack additively.
122	 */
123	interface Modifier<Subject> {
124	  appliesTo: (subject: Subject) => boolean;
125	  rate: number;
126	}
127	
128	const combinedRateOf = <Subject>(
129	  modifiers: Modifier<Subject>[],
130	  subject: Subject,
131	): number => sumOf(modifiers, ({ appliesTo, rate }) => (appliesTo(subject) ? rate : 0));
132	
133	/** Item-specific modifiers are levied on the affected item's own base premium. */
134	const ITEM_MODIFIERS: Modifier<Item>[] = [
135	  { appliesTo: isCursed, rate: CURSE_SURCHARGE },
136	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
137	];
138	
139	const itemSurchargeFor = (item: Item): number =>
140	  basePremiumFor(item) * combinedRateOf(ITEM_MODIFIERS, item);
141	
142	const LOYALTY_THRESHOLD_YEARS = 2;
143	
144	/**
145	 * The circumstances a single quote is issued under: who is being quoted, and
146	 * where this contract falls in their history with the MHPCO. Policy-wide
147	 * modifiers are decided from this alone.
148	 */
149	interface QuoteContext {
150	  customer: Customer;
151	  isFollowUpContract: boolean;
152	}
153	
154	const isLongStanding = ({ customer }: QuoteContext): boolean =>
155	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
156	
157	const followsAnEarlierContract = ({ isFollowUpContract }: QuoteContext): boolean =>
158	  isFollowUpContract;
159	
160	const appliesToEveryQuote = (): boolean => true;
161	
162	/** Policy-wide modifiers are levied on the whole policy's base premium. */
163	const POLICY_MODIFIERS: Modifier<QuoteContext>[] = [
164	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT },
165	  { appliesTo: appliesToEveryQuote, rate: INITIAL_ASSESSMENT_SURCHARGE },
166	  { appliesTo: followsAnEarlierContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT },
167	];
168	
169	/**
170	 * Item-specific modifiers are levied on the affected item's own base premium,
171	 * while policy-wide modifiers are levied on the policy base premium — the sum
172	 * of the item base premiums, before any item surcharge is added.
173	 */
174	const quote = (step: QuoteStep, context: QuoteContext): StepResult => {
175	  const policyBasePremium = sumOf(alikeComponentGroups(step.items), basePremiumForGroup);
176	  const itemSurcharges = sumOf(step.items, itemSurchargeFor);
177	  const policyAdjustment = policyBasePremium * combinedRateOf(POLICY_MODIFIERS, context);
178	  return {
179	    premium: roundUpToWholeG(
180	      policyBasePremium + itemSurcharges + policyAdjustment + PROCESSING_FEE,
181	    ),
182	  };
183	};
184	
185	const insuranceValueFor = (item: Item): number => {
186	  const insuranceValue = INSURANCE_VALUES[item.type];
187	  if (insuranceValue === undefined) throw new Error(`Unknown item type: ${item.type}`);
188	  return insuranceValue;
189	};
190	
191	/** A policy created by a quote step, against which later claims are settled. */
192	interface Policy {
193	  items: Item[];
194	  remainingCap: number;
195	}
196	
197	const policyFor = (step: QuoteStep): Policy => ({
198	  items: step.items,
199	  remainingCap: sumOf(step.items, insuranceValueFor) * CAP_MULTIPLE_OF_INSURANCE_SUM,
200	});
201	
202	/**
203	 * Damage to a very strongly enchanted item is only half reimbursed. This
204	 * threshold is deliberately distinct from the premium side's
205	 * HIGH_ENCHANTMENT_THRESHOLD: the same attribute is read by two unrelated rules.
206	 */
207	const ENCHANTMENT_HALVING_REIMBURSEMENT = 8;
208	const HALF_REIMBURSEMENT_RATE = 0.5;
209	const FULL_REIMBURSEMENT_RATE = 1;
210	
211	const isTooEnchantedToFullyReimburse = (item: Item): boolean =>
212	  item.enchantment !== undefined && item.enchantment >= ENCHANTMENT_HALVING_REIMBURSEMENT;
213	
214	const reimbursementRateFor = (item: Item): number =>
215	  isTooEnchantedToFullyReimburse(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
216	
217	const insuredItemFor = (damage: Damage, policy: Policy): Item => {
218	  const item = policy.items.find(({ type }) => type === damage.itemType);
219	  if (item === undefined) throw new Error(`Item not insured: ${damage.itemType}`);
220	  return item;
221	};
222	
223	/** The clause is applied to the damage first; the deductible comes off the result. */
224	const payoutForDamage = (damage: Damage, policy: Policy): number => {
225	  const reimbursed = damage.amount * reimbursementRateFor(insuredItemFor(damage, policy));
226	  return reimbursed - DEDUCTIBLE_PER_DAMAGE;
227	};
228	
229	/** Claims name the quote step that created the policy they are settled against. */
230	const policyAt = (policies: Map<number, Policy>, step: number): Policy => {
231	  const policy = policies.get(step);
232	  if (policy === undefined) throw new Error(`No policy at step ${step}`);
233	  return policy;
234	};
235	
236	/**
237	 * A claim both reports a payout and draws down the policy's cap, so settling one
238	 * yields the settled policy rather than mutating it: successive claims against
239	 * the same policy are then an explicit chain, not a hidden shared-state effect.
240	 */
241	const claim = (
242	  step: ClaimStep,
243	  policy: Policy,
244	): { result: StepResult; policy: Policy } => {
245	  const payout = sumOf(step.incident.damages, (damage) => payoutForDamage(damage, policy));
246	  const remainingCap = policy.remainingCap - payout;
247	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
248	};
249	
250	/**
251	 * Steps are not independent: a quote's premium depends on whether an earlier
252	 * quote in the same scenario already established a contract, and a claim is
253	 * settled against the policy an earlier quote created.
254	 */
255	export const runScenario = (scenario: Scenario): ScenarioResult => {
256	  const policies = new Map<number, Policy>();
257	  let hasQuoted = false;
258	
259	  const results = scenario.steps.map((step, index) => {
260	    if (step.op === "quote") {
261	      const result = quote(step, {
262	        customer: scenario.customer,
263	        isFollowUpContract: hasQuoted,
264	      });
265	      policies.set(index, policyFor(step));
266	      hasQuoted = true;
267	      return result;
268	    }
269	
270	    const settled = claim(step, policyAt(policies, step.policy));
271	    policies.set(step.policy, settled.policy);
272	    return settled.result;
273	  });
274	
275	  return { results };
276	};
